import React, { useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useCallback } from 'react';
import './ExpandedView.css';

const ExpandedView = ({ isOpen, onClose, profileData }) => {
  const expandedRef = useRef(null);

  // Handle click outside to close
  const handleClickOutside = useCallback((event) => {
    if (expandedRef.current && !expandedRef.current.contains(event.target)) {
      onClose();
    }
  }, [onClose]);

  useEffect(() => {
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [handleClickOutside]);

  // Portfolio data
  const portfolioProjects = [
    {
      title: "Interactive Profile Card",
      description: "A modern profile card with laser animations and interactive elements built with React and Framer Motion.",
      tags: ["React", "Framer Motion", "CSS Animations"],
      image: "/portfolio/profile-card.jpg",
      link: "https://github.com/yourusername/profile-card"
    },
    {
      title: "Project 2",
      description: "Description of your second project",
      tags: ["React", "Node.js", "MongoDB"],
      image: "/portfolio/project2.jpg",
      link: "https://github.com/yourusername/project2"
    },
    {
      title: "Project 3",
      description: "Description of your third project",
      tags: ["TypeScript", "Next.js", "Tailwind"],
      image: "/portfolio/project3.jpg",
      link: "https://github.com/yourusername/project3"
    }
  ];

  // Animation variants
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        duration: 0.3,
        staggerChildren: 0.1
      }
    },
    exit: {
      opacity: 0,
      transition: { duration: 0.2 }
    }
  };

  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1,
      transition: { duration: 0.5 }
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          className="expanded-overlay"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={onClose}
        >
          <motion.div
            ref={expandedRef}
            className="expanded-content"
            variants={containerVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
            onClick={e => e.stopPropagation()}
          >
            <motion.button
              className="close-button"
              onClick={onClose}
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.9 }}
            >
              ×
            </motion.button>

            <motion.div className="expanded-image-container" variants={itemVariants}>
              <img
                src={profileData.image}
                alt={profileData.name}
                className="expanded-image"
              />
            </motion.div>

            <motion.h1
              className="expanded-name"
              variants={itemVariants}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: 0.2 }}
            >
              {profileData.name}
            </motion.h1>

            <motion.p
              className="expanded-title"
              variants={itemVariants}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: 0.3 }}
            >
              {profileData.title}
            </motion.p>

            <motion.p
              className="expanded-bio"
              variants={itemVariants}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: 0.4 }}
            >
              {profileData.bio}
            </motion.p>

            <motion.div
              className="social-links"
              variants={itemVariants}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: 0.5 }}
            >
              {profileData.socialLinks.map((link, index) => (
                <motion.a
                  key={index}
                  href={link.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  whileHover={{ scale: 1.1 }}
                  whileTap={{ scale: 0.9 }}
                  className="social-link"
                >
                  {link.icon}
                </motion.a>
              ))}
            </motion.div>

            <motion.div
              className="contact-info"
              variants={itemVariants}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: 0.6 }}
            >
              <p>{profileData.email}</p>
              <p>{profileData.phone}</p>
              <p>{profileData.location}</p>
            </motion.div>

            {/* Portfolio Section */}
            <motion.div variants={itemVariants} className="portfolio-section">
              <h3 className="section-title">Portfolio</h3>
              <div className="portfolio-grid">
                {portfolioProjects.map((project, index) => (
                  <motion.div
                    key={index}
                    className="portfolio-item"
                    variants={itemVariants}
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                  >
                    <div className="portfolio-item-content">
                      <h4>{project.title}</h4>
                      <p>{project.description}</p>
                      <div className="tags">
                        {project.tags.map((tag, idx) => (
                          <span key={idx} className="tag">{tag}</span>
                        ))}
                      </div>
                      <a href={project.link} target="_blank" rel="noopener noreferrer" className="project-link">
                        View Project
                      </a>
                    </div>
                  </motion.div>
                ))}
              </div>
            </motion.div>

            {/* Contact Section */}
            <motion.div variants={itemVariants} className="contact-section">
              <h3 className="section-title">Contact</h3>
              <div className="contact-info">
                <div className="contact-item">
                  <span className="icon">📧</span>
                  <a href={`mailto:${profileData.email}`}>{profileData.email}</a>
                </div>
                <div className="contact-item">
                  <span className="icon">📱</span>
                  <a href={`tel:${profileData.phone}`}>{profileData.phone}</a>
                </div>
                <div className="contact-item">
                  <span className="icon">📍</span>
                  <span>{profileData.location}</span>
                </div>
              </div>
            </motion.div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default React.memo(ExpandedView);
